<?php $csrfJson = json_encode($csrfToken); ?>
<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulador GPS | GUIAR</title>
<style>
body{font-family:Arial,sans-serif;background:#f4f7fb;color:#172033;margin:0;padding:32px}.card{max-width:850px;margin:auto;background:white;border-radius:16px;padding:28px;box-shadow:0 8px 30px #17203312}h1{margin-top:0}.grid{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}label{display:grid;gap:7px;font-weight:600}select,input,textarea,button{font:inherit;padding:11px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:120px;font-family:monospace}.buttons{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}button{cursor:pointer;background:#155eef;color:white;border:0}button.secondary{background:#475569}button.restore{background:#b42318}#status{padding:12px;background:#f1f5f9;border-radius:8px}.muted{color:#64748b}
</style></head>
<body><main class="card"><p><a href="<?= BASE_URL ?>/routes.php?action=dashboardAdm">← Painel administrativo</a></p><h1>Simulador GPS</h1><p class="muted">A rota segue as ruas entre a posição atual do entregador e os pedidos em aberto. As coordenadas simuladas ficam visíveis no mapa.</p>
<div class="grid"><label>Entregador<select id="driver"><?php foreach($entregadores as $e): ?><option value="<?= (int)$e['id_entregador'] ?>" data-name="<?= htmlspecialchars($e['nome_completo'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($e['nome_completo'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Intervalo entre posições (segundos)<input id="interval" type="number" min="1" max="60" value="2"></label></div>
<label style="margin-top:16px">Pontos de entrega do entregador selecionado<textarea id="route" readonly placeholder="Carregando pontos de entrega…"></textarea></label>
<div class="buttons"><button id="start">Iniciar</button><button id="pause" class="secondary">Pausar</button><button id="restart" class="secondary">Reiniciar trajeto</button><button id="restore" class="restore">Restaurar posição original</button></div><div id="status">Estado: parado</div></main>
<script>
const csrf=<?= $csrfJson ?>, endpoint='<?= BASE_URL ?>/routes.php?action=apiSimuladorGPS';let path=[],index=0,timer=null,running=false,destinations=[],currentPosition=null;
const statusEl=document.getElementById('status'),driver=document.getElementById('driver');function say(s){statusEl.textContent=s}
async function send(operation,coords={}){const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,id_entregador:driver.value,operation,...coords})});const data=await res.json();if(!res.ok||!data.success)throw Error(data.error||'Falha de comunicação.');return data}
async function loadDestinations(){running=false;clearTimeout(timer);document.getElementById('route').value='Carregando pontos de entrega…';try{const d=await send('destinations');destinations=d.points;currentPosition=d.current;document.getElementById('route').value=destinations.length?destinations.map(p=>`${p.latitude.toFixed(6)}, ${p.longitude.toFixed(6)} — ${p.label}`).join('\n'):'Nenhum pedido em aberto com coordenadas válidas.';say(destinations.length?`${destinations.length} ponto(s) de entrega carregado(s) para ${d.driver}.`:'Este entregador não possui pedidos em aberto com latitude e longitude.')}catch(e){document.getElementById('route').value='';say('Erro ao carregar pontos: '+e.message)}}
function distanceMeters(a,b){const rad=n=>n*Math.PI/180,lat1=rad(a[1]),lat2=rad(b[1]),dlat=lat2-lat1,dlon=rad(b[0]-a[0]),h=Math.sin(dlat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dlon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function densify(coords,spacing=20){const out=[];for(let i=0;i<coords.length-1;i++){const a=coords[i],b=coords[i+1],steps=Math.max(1,Math.ceil(distanceMeters(a,b)/spacing));for(let n=0;n<steps;n++){const t=n/steps;out.push([a[1]+(b[1]-a[1])*t,a[0]+(b[0]-a[0])*t])}}if(coords.length)out.push([coords.at(-1)[1],coords.at(-1)[0]]);return out}
async function getRoadRoute(){if(!currentPosition||currentPosition.latitude===null||currentPosition.longitude===null)throw Error('O entregador ainda não possui posição atual. Registre uma localização antes da demonstração.');const coords=[[currentPosition.longitude,currentPosition.latitude],...destinations.map(p=>[p.longitude,p.latitude])];const url='https://router.project-osrm.org/route/v1/driving/'+coords.map(p=>p.join(',')).join(';')+'?overview=full&geometries=geojson&steps=false';const res=await fetch(url);if(!res.ok)throw Error('Serviço de rotas viárias indisponível. Tente novamente.');const data=await res.json();if(data.code!=='Ok'||!data.routes?.[0]?.geometry?.coordinates?.length)throw Error('Não foi encontrada uma rota pelas ruas para estes pontos.');return densify(data.routes[0].geometry.coordinates)}
async function tick(){if(!running)return;try{const p=path[index],d=await send('update',{latitude:p[0],longitude:p[1]});say(`SIMULADO • ${driver.selectedOptions[0].dataset.name} • ${index+1}/${path.length} • ${Number(d.latitude).toFixed(6)}, ${Number(d.longitude).toFixed(6)}`);index=(index+1)%path.length}catch(e){running=false;clearTimeout(timer);say('Erro de comunicação: '+e.message);return}timer=setTimeout(tick,Math.max(1,Number(document.getElementById('interval').value)||2)*1000)}
document.getElementById('start').onclick=async()=>{try{if(!destinations.length)await loadDestinations();if(!destinations.length)throw Error('Não há pontos de entrega disponíveis para simular.');say('Calculando trajeto pelas ruas…');path=await getRoadRoute();await send('start');index=0;running=true;clearTimeout(timer);say(`Rota viária pronta: ${path.length} posições intermediárias.`);tick()}catch(e){say('Erro: '+e.message)}};
document.getElementById('pause').onclick=()=>{running=false;clearTimeout(timer);say('Estado: pausado')};document.getElementById('restart').onclick=()=>{index=0;if(running){clearTimeout(timer);tick()}else say('Estado: trajeto reiniciado')};document.getElementById('restore').onclick=async()=>{running=false;clearTimeout(timer);try{const d=await send('restore');say(`Posição original restaurada: ${d.latitude??'—'}, ${d.longitude??'—'}`)}catch(e){say('Erro: '+e.message)}};
driver.addEventListener('change',loadDestinations);loadDestinations();
</script></body></html>
